import fetch from"node-fetch";const API="https://api.escuelajs.co/api/v1";async function fetchData(t){const o=await fetch(t);return await o.json()}const anotherFunction=async t=>{try{const o=await fetchData(`${t}/products`),a=await fetchData(`${t}/products/${o[0].id}`),c=await fetchData(`${t}/categories/${a.category.id}`);console.log(o),console.log(a.title),console.log(c.name)}catch(t){console.log(t)}};anotherFunction(API);